/* Treatment-stage presentation inside the patient's Manage Action suggestion column. */
(()=>{
function render(review){return `<section class="task-culture-review"><span class="intake-eyebrow">CULTURE-GUIDED TREATMENT REVIEW</span><h3>${esc(review.stage)}</h3><p>${esc(review.guidance)}</p>${review.resistanceAlerts.map(a=>`<div class="task-guidance-holds" role="note">${esc(a)}</div>`).join('')}${review.reports.length?review.reports.map(r=>`<article class="therapy-report"><div class="task-rule-heading"><b>${esc(r.accession||r.testId)}</b><span>${esc(r.status)}</span></div><p><b>${esc(r.organism||r.value||'Organism not identified')}</b></p><p class="mini">Report ${esc(r.id)} · available ${r.availableAt?esc(fmt(r.availableAt)):'time not supplied'}</p>${r.conflict?'<p class="task-guidance-holds">Conflicting report — laboratory clarification required.</p>':''}${r.astRows.length?`<div class="scroll"><table><thead><tr><th>Reported agent</th><th>AST</th></tr></thead><tbody>${r.astRows.map(x=>`<tr><td>${esc(x.agent)}</td><td><span class="pill ${x.interpretation==='R'?'red':'amber'}">${esc(x.interpretation)}</span></td></tr>`).join('')}</tbody></table></div><p class="mini">S is a reported laboratory result, not an order. I requires breakpoint / exposure interpretation. No target dose is inferred from AST alone.</p>`:'<p class="mini">No current AST reported. Do not infer susceptibility or wait for it to start urgent empirical therapy.</p>'}${r.positive?`<div class="therapy-suggestion"><b>Suggested next action</b><p>${r.susceptible.length?'Review the reported susceptible options: '+esc(r.susceptible.map(x=>x.agent).join(', '))+'. Verify the full regimen and source before a change.':'Request / review susceptibility and correlate the organism with the infection source.'}</p><p>${r.final?'Final / corrected report: consider a targeted plan; narrowing remains a clinician decision.':'Preliminary report: any organism-directed change is provisional; await report updates without delaying treatment.'}</p></div>`:''}<p class="mini">${r.decision?'Recorded decision: '+esc(r.decision.value)+' · '+esc(r.decision.note):r.ack?'Current report acknowledged · treatment decision pending':'Current report needs acknowledgment before a culture-to-treatment decision.'}</p><button class="btn" type="button" onclick="fnDyn.resultReview('${esc(r.testId)}',${!!r.ack})">${r.ack?'Review treatment decision':'Review / acknowledge this report'}</button></article>`).join(''):'<p class="mini">No current culture result is available for this encounter. No organism or AST is generated.</p>'}${review.cancelledReports?`<p class="mini">${review.cancelledReports} cancelled report(s) excluded; earlier versions are not revived.</p>`:''}${review.positiveReports?`<details><summary>De-escalation checks</summary><p>${review.canConsiderDeescalation?'A narrowing review is available after acknowledgment; the prescriber must still verify source, coverage, susceptibility and local policy.':'Automatic narrowing is withheld. Use a clinician-directed review / revision for complex cases.'}</p>${review.constraints.map(x=>`<p>${esc(x)}</p>`).join('')}<p>Mixed isolates, resistance mechanisms, ongoing high-risk FN, source control and concurrent infection must be reviewed before removing coverage. No automatic stop date is created.</p></details>`:''}<details><summary>Empiric, targeted and definitive therapy</summary>${review.definitions.map(x=>`<p><b>${esc(x.title)}:</b> ${esc(x.text)}</p>`).join('')}</details><p class="mini">Evidence: <a href="${FNClinicalGuidelines.sources.fn.url}" target="_blank" rel="noopener">IDSA FN recommendations 15–19</a> · <a href="${FNClinicalGuidelines.sources.agiho.url}" target="_blank" rel="noopener">AGIHO reassessment</a> · <a href="${FNClinicalGuidelines.sources.amr.url}" target="_blank" rel="noopener">IDSA AMR 2026</a></p></section>`}
window.fnTherapyReview={render};
})();
